// Get the raw HTML from the previous node
const html = $input.first().json.products_raw;

// Grab the search term from earlier in the workflow
const searchTerm = $('Set Search Term').first().json.search_term;

if (!html || !Array.isArray(html) || html.length === 0) {
  throw new Error('No products found. Amazon may have blocked the request or the page structure changed.');
}

// Helper: extract text by regex pattern
function extractText(html, pattern) {
  const match = html.match(pattern);
  return match ? match[1].replace(/<[^>]*>/g, '').trim() : null;
}

// Helper: extract href
function extractHref(html, pattern) {
  const match = html.match(pattern);
  return match ? match[1].trim() : null;
}

const results = [];

for (let i = 0; i < Math.min(5, html.length); i++) {
  const block = html[i];

  // Skip sponsored results
  if (block.includes('AdHolder') || block.includes('s-sponsored-label')) {
    // Try to get the next one
    continue;
  }

  // Extract product name — inside h2 > span
  let name = null;
  const nameMatch = block.match(/<h2[^>]*>[\s\S]*?<span[^>]*>([\s\S]*?)<\/span>[\s\S]*?<\/h2>/);
  if (nameMatch) {
    name = nameMatch[1].replace(/<[^>]*>/g, '').trim();
  }

  // Extract product link — the <a> inside h2
  let link = null;
  const linkMatch = block.match(/<h2[^>]*>[\s\S]*?<a[^>]*href="([^"]+)"/);
  if (linkMatch) {
    const href = linkMatch[1];
    // Make sure it's a full URL
    link = href.startsWith('http') ? href : 'https://www.amazon.com' + href;
    // Clean up tracking params — keep it to the /dp/ part
    const dpMatch = link.match(/(https:\/\/www\.amazon\.com\/[^?]+)/);
    if (dpMatch) link = dpMatch[1];
  }

  // Extract category — look for department breadcrumb or derive from search
  let category = searchTerm.charAt(0).toUpperCase() + searchTerm.slice(1);
  const catMatch = block.match(/aria-label="[^"]*in ([^"]+)"/);
  if (catMatch) {
    category = catMatch[1].trim();
  }

  if (name && link) {
    results.push({
      rank: results.length + 1,
      category: category,
      name: name,
      link: link,
      scraped_at: new Date().toISOString()
    });
  }

  if (results.length >= 5) break;
}

if (results.length === 0) {
  throw new Error('Could not parse any products. Check the HTML selectors.');
}

return results.map(r => ({ json: r }));
